/// <summary>
/// find or creates record
/// </summary>
/// <param name = "_ndxUtilitasDataRecId">NDXUtilitasData RecId</param>
/// <param name = "_record">UtilitasDataContract record</param>
/// <returns>NDXUtilitasDataRelatedItems record</returns>
static public NDXUtilitasDataRelatedItems findOrCreateByObject(RefRecId _ndxUtilitasDataRecId, Niedax.Utilitas.UtilitasDataContract _record)
{
    NDXUtilitasData lNDXUtilitasData;
    NDXUtilitasDataRelatedItems lNDXUtilitasDataRelatedItems;

    //ToDo: Language
    EcoResProductRelationType lEcoResProductRelationType;
    EcoResProductRelationTypeTranslation lEcoResProductRelationTypeTranslation;

    if(_ndxUtilitasDataRecId)
    {
        lNDXUtilitasDataRelatedItems = NDXUtilitasDataRelatedItems::findRecId(_ndxUtilitasDataRecId, _record, true);

        if(!lNDXUtilitasDataRelatedItems && _record != null)
        {
            lNDXUtilitasDataRelatedItems.NDXUtilitasDataRefRecId = _ndxUtilitasDataRecId;
            lNDXUtilitasDataRelatedItems.insert();
        }

        if(lNDXUtilitasDataRelatedItems)
        {
            lNDXUtilitasData = NDXUtilitasData::findOrCreateByObject(_record); 

            lNDXUtilitasDataRelatedItems.ScopeId = _record.ScopeId;
            lNDXUtilitasDataRelatedItems.ScopeDescription = _record.ScopeDescription;
            lNDXUtilitasDataRelatedItems.RelatedNDXUtilitasDataRefRecId = lNDXUtilitasData.RecId;

            ttsbegin;
            lNDXUtilitasDataRelatedItems.doUpdate();
            ttscommit;
        }
    }

    return lNDXUtilitasDataRelatedItems;
}

/// <summary>
/// find a record
/// </summary>
/// <param name = "_ndxUtilitasDataRecId">NDXUtilitasData RecId</param>
/// <param name = "_record">UtilitasDataContract record</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>NDXUtilitasDataRelatedItems record</returns>
static public NDXUtilitasDataRelatedItems findRecId(RefRecId _ndxUtilitasDataRecId, Niedax.Utilitas.UtilitasDataContract _record, boolean _forUpdate = false)
{
    NDXUtilitasData lNDXUtilitasData;
    NDXUtilitasDataRelatedItems lNDXUtilitasDataRelatedItems;

    Name scope;
    ItemIdBase itemId;

    lNDXUtilitasDataRelatedItems.selectForUpdate(_forUpdate);

    if(_ndxUtilitasDataRecId && _record != null)
    {
        scope = _record.ScopeID;
        itemId = _record.ItemId;

        lNDXUtilitasData = NDXUtilitasData::find(itemId);

        if(lNDXUtilitasData)
        {
            select lNDXUtilitasDataRelatedItems
                where lNDXUtilitasDataRelatedItems.NDXUtilitasDataRefRecId == _ndxUtilitasDataRecId
                && lNDXUtilitasDataRelatedItems.RelatedNDXUtilitasDataRefRecId == lNDXUtilitasData.RecId
                && lNDXUtilitasDataRelatedItems.ScopeId == scope;
        }
    }
    return lNDXUtilitasDataRelatedItems;
}
